graphql.query:
mutation Login($username: String!, $password: String!) {
  login(username: $username, password: $password) {
    token
    user {
      id
      fullName
      role
    }
  }
}

query {
  account(id: 3) {
    number
    balance
    owner {
      fullName
    }
  }
}

mutation {
  transfer(fromAccountId: 3, toAccountId: 1, amount: 1) {
    id
    amount
  }
}

mutation {
  createCard(accountId: 3, number: "0000 0000 0000 0000", cvv: "000", expiry: "01/30") {
    id
  }
}
